import {test} from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,rmSync,existsSync} from 'node:fs';import {tmpdir} from 'node:os';import {join} from 'node:path';import {BridgeClient} from '../desktop/bridge-client.mjs';
const secure={isEncryptionAvailable:()=>true,encryptString:s=>Buffer.from(s),decryptString:b=>b.toString()};
test('offline disconnection persists revocation and sends no further read jobs',async()=>{const dir=mkdtempSync(join(tmpdir(),'omni-revoke-'));let client;try{let offline=true,polled=false;const fetcher=async url=>{if(offline)throw Error('offline');if(url.endsWith('/device/poll'))polled=true;return Response.json({ok:true});};client=new BridgeClient({credentialPath:join(dir,'c.bin'),safeStorage:secure,store:{},openURL:()=>{},deviceName:'PC',fetcher,origin:'https://omni.test'});client.credentials={token:'a'.repeat(64)};client.persist();await client.disconnect();client.stop();assert.equal(client.credentials.revocationPending,true);assert.equal(client.status,'revoking');assert.equal(existsSync(join(dir,'c.bin')),true);offline=false;client.stopped=false;await client.tick();client.stop();assert.equal(client.status,'disconnected');assert.equal(polled,false);assert.equal(existsSync(join(dir,'c.bin')),false);}finally{client?.stop();rmSync(dir,{recursive:true});}});
